SELECT "REGION", COUNT(*) AS "PARTIAL_count_0", COUNT("ID") AS "PARTIAL_count_1", SUM("SCORE") AS "PARTIAL_sum_2", MIN("TS") AS "PARTIAL_min_3", MAX("TS") AS "PARTIAL_max_4", SUM("SCORE") AS "PARTIAL_avg_sum_5", COUNT("SCORE") AS "PARTIAL_avg_cnt_5", COUNT("SCORE") AS "PARTIAL_stat_cnt_6", SUM("SCORE") AS "PARTIAL_stat_sum_6", SUM("SCORE" * "SCORE") AS "PARTIAL_stat_sumsq_6", COUNT("SCORE") AS "PARTIAL_stat_cnt_7", SUM("SCORE") AS "PARTIAL_stat_sum_7", SUM("SCORE" * "SCORE") AS "PARTIAL_stat_sumsq_7", COUNT("SCORE") AS "PARTIAL_stat_cnt_8", SUM("SCORE") AS "PARTIAL_stat_sum_8", SUM("SCORE" * "SCORE") AS "PARTIAL_stat_sumsq_8", COUNT("SCORE") AS "PARTIAL_stat_cnt_9", SUM("SCORE") AS "PARTIAL_stat_sum_9", SUM("SCORE" * "SCORE") AS "PARTIAL_stat_sumsq_9" FROM (aliased) GROUP BY "REGION"